	private static ValueConstant literal(boolean value) {
		return new ValueConstant(SimpleValueFactory.getInstance().createLiteral(value));
	}

	private static RuntimeFeedbackContract stampRefusal(TupleExpr node) {
		RuntimeFeedbackContract contract = contract(0);
		node.setRuntimeFeedbackContract(contract);
		node.setStringMetricPlanned(DISPOSITION, "population-refused");
		node.setStringMetricPlanned("optimizer.frontierMappedSessionRefusalReason",
				"logical_population_not_admitted");
		node.setStringMetricPlanned("optimizer.frontierSemanticPopulation", "unavailable");
		node.setDoubleMetricPlanned(GENERATION, 17.0d);
		node.setLongMetricPlanned("selected-long", 19L);
		node.setResultSizeEstimate(3.0d);
		node.setCostEstimate(7.0d);
		node.setCostFeedbackExpectedRows(3.0d);
		node.setCostFeedbackExpectedWorkRows(7.0d);
		node.setCostFeedbackTrackingEnabled(true);
		return contract;
	}

	private static void assertLocalMetadata(TupleExpr selected, TupleExpr installed) {
		assertEquals(selected.getStringMetricsPlanned(), installed.getStringMetricsPlanned());
		assertEquals(selected.getDoubleMetricsPlanned(), installed.getDoubleMetricsPlanned());
		assertEquals(selected.getLongMetricsPlanned(), installed.getLongMetricsPlanned());
		assertEquals(selected.getResultSizeEstimate(), installed.getResultSizeEstimate());
		assertEquals(selected.getCostEstimate(), installed.getCostEstimate());
		assertEquals(selected.getCostFeedbackExpectedRows(), installed.getCostFeedbackExpectedRows());
		assertEquals(selected.getCostFeedbackExpectedWorkRows(), installed.getCostFeedbackExpectedWorkRows());
		assertEquals(selected.isCostFeedbackTrackingEnabled(), installed.isCostFeedbackTrackingEnabled());
	}

	private static RuntimeFeedbackContract contract(int flags) {
		return new RuntimeFeedbackContract(new RuntimeFeedbackDescriptor() {
		}, RuntimeFeedbackContract.PredictionVector.UNKNOWN, RuntimeFeedbackContract.PredictionVector.UNKNOWN,
				1.0d, 1.0d, 1.0d, Double.POSITIVE_INFINITY, RuntimeFeedbackContract.SemanticKind.ORDINARY,
				RuntimeFeedbackContract.Algorithm.UNKNOWN, RuntimeFeedbackContract.Access.UNKNOWN,
				0, 1L, 1L, 1L, flags);
	}

	private static StatementPattern storage() {
		return new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
	}

